maximum-score-after-splitting-a-string:
class Solution:
    def maxScore(self, s: str) -> int:
        ones = s.count('1')
        zeros = 0
        best = 0
        for i in range(len(s) - 1):
            if s[i] == '0':
                zeros += 1
            else:
                ones -= 1
            if zeros + ones > best:
                best = zeros + ones
        return best

mean-of-array-after-removing-some-elemen:
class Solution:
    def trimMean(self, arr: list[int]) -> float:
        a = sorted(arr)
        k = len(a) // 20
        sub = a[k:len(a) - k]
        return sum(sub) / len(sub)

merge-strings-alternately:
class Solution:
    def mergeAlternately(self, word1: str, word2: str) -> str:
        out = []
        for i in range(max(len(word1), len(word2))):
            if i < len(word1):
                out.append(word1[i])
            if i < len(word2):
                out.append(word2[i])
        return ''.join(out)

minimum-changes-to-make-alternating-bina:
class Solution:
    def minOperations(self, s: str) -> int:
        a = 0
        b = 0
        for i, c in enumerate(s):
            if c == str(i % 2):
                a += 1
            else:
                b += 1
        return min(a, b)

minimum-cost-to-move-chips-to-the-same-p:
class Solution:
    def minCostToMoveChips(self, position: list[int]) -> int:
        odd = 0
        for p in position:
            if p % 2:
                odd += 1
        return min(odd, len(position) - odd)

minimum-distance-to-the-target-element:
class Solution:
    def getMinDistance(self, nums: list[int], target: int, start: int) -> int:
        best = len(nums)
        for i, v in enumerate(nums):
            if v == target:
                d = abs(i - start)
                if d < best:
                    best = d
        return best

minimum-index-sum-of-two-lists:
class Solution:
    def findRestaurant(self, list1: list[str], list2: list[str]) -> list[str]:
        idx = {w: i for i, w in enumerate(list1)}
        best = 10 ** 9
        out = []
        for j, w in enumerate(list2):
            if w in idx:
                total = idx[w] + j
                if total < best:
                    best = total
                    out = [w]
                elif total == best:
                    out.append(w)
        return out

minimum-number-of-moves-to-seat-everyone:
class Solution:
    def minMovesToSeat(self, seats: list[int], students: list[int]) -> int:
        a = sorted(seats)
        b = sorted(students)
        total = 0
        for x, y in zip(a, b):
            total += abs(x - y)
        return total

minimum-operations-to-make-the-array-inc:
class Solution:
    def minOperations(self, nums: list[int]) -> int:
        ops = 0
        for i in range(1, len(nums)):
            if nums[i] <= nums[i - 1]:
                ops += nums[i - 1] + 1 - nums[i]
                nums[i] = nums[i - 1] + 1
        return ops
